import struct, json, re, sys
def f32(x):
    return struct.unpack('f', struct.pack('f', x))[0]
edges = {100002: ((0.0, 100.0), (37123.7, 100.0), (37123.7, -100.0), (0.0, -100.0)),
         100003: None, 100004: None}
samples = []
for line in open('/tmp/views-notes/lw4.out'):
    m = re.search(r'"id":(\d+),"at":\[([-\d.e]+),([-\d.e]+)\].*OUT (\{.*\}) \[0\]', line)
    if not m:
        continue
    wid = int(m.group(1)); ax = float(m.group(2)); ay = float(m.group(3))
    out = json.loads(m.group(4))
    samples.append((wid, ax, ay, out['from'], out['to']))
print(len(samples))
# the true edge coordinates (exact)
def true_coords(wid, fr, to):
    # round to nearest plausible exact value
    def r(v):
        for cand in (0.0, 100.0, -100.0, 37123.7, 5000.0, 60000.3, 1000.123, 90000.9, -7000.77, -6900.77, -7100.77):
            if abs(v - cand) < 0.01:
                return cand
        return None
    return [r(fr[0]), r(fr[1])], [r(to[0]), r(to[1])]
cands = []
for s in [0.05, 0.1, 0.2, 0.025, 0.04, 0.5, 1.0, 0.125, 0.0625]:
    for c in [0, 100, 200, 250, 256, 300, 400, 500, 512, 600, 640, 800, 1000, 1024, 1200, 1280, 1500, 1600, 2000, 2048, 4000]:
        for cy in [c, 0, 100, 200, 250, 256, 300, 360, 400, 450, 480, 500, 512, 600, 720, 768, 800, 1000, 1024]:
            for flip in (False, True):
                ok = 0
                for wid, ax, ay, fr, to in samples:
                    tf, tt = true_coords(wid, fr, to)
                    good = True
                    for (tx, ty), (ox, oy) in ((tf, fr), (tt, to)):
                        if tx is None or ty is None:
                            good = False; break
                        px = f32((tx - ax) * s + c)
                        bx = (px - c) / s + ax
                        if flip:
                            py = f32((ay - ty) * s + cy)
                            by = ay - (py - cy) / s
                        else:
                            py = f32((ty - ay) * s + cy)
                            by = (py - cy) / s + ay
                        if bx != ox or by != oy:
                            good = False; break
                    if good:
                        ok += 1
                cands.append((ok, s, c, cy, flip))
cands.sort(reverse=True)
for x in cands[:20]:
