#!/usr/bin/env python3
"""each2.py [-f base.bimcraft] cmds.txt
Each line: `setup cmds ;; ... || test cmds ;; ...`. The setup runs on the ORIGINAL (from base) and
is saved; the test commands then run on both programs from that file. Prints SAME/DIFF."""
import os, subprocess, sys, tempfile, shutil, re
ORIG = '/workspace/executable'
MINE = os.environ['MINE']
G = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
a = sys.argv[1:]
base = None
show_same = False
while a and a[0].startswith('-'):
    if a[0] == '-f': base = a[1]; a = a[2:]
    elif a[0] == '-v': show_same = True; a = a[1:]
    else: break
lines = [l.rstrip('\n') for l in open(a[0]) if l.strip() and not l.startswith('#')]
def norm(s):
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    return G.sub(rep, s)
same = 0
scratch = os.environ.get('SCRATCH', '/tmp/views-notes')
for l in lines:
    if '||' in l:
        setup, test = l.split('||', 1)
    else:
        setup, test = '', l
    d = tempfile.mkdtemp(prefix='e2', dir=scratch)
    inp = os.path.join(d, 'in.bimcraft')
    args = [ORIG, 'run']
    if base:
        args.append(os.path.abspath(base))
    for c in setup.split(' ;; '):
        if c.strip():
            args += ['--cmd', c.strip()]
    args += ['--save', inp]
    p = subprocess.run(args, capture_output=True, cwd=d, timeout=120)
    if p.returncode != 0:
        print('SETUP FAILED', l, p.stderr.decode()[:300])
        shutil.rmtree(d)
        continue
    outs = []
    for exe in (ORIG, MINE):
        args = [exe, 'run', inp]
        for c in test.split(' ;; '):
            if c.strip():
                args += ['--cmd', c.strip()]
        p = subprocess.run(args, capture_output=True, cwd=d, timeout=120)
        o = p.stdout.decode('utf-8', 'replace').strip().split('\n')[1:]
        outs.append(norm('OUT ' + '\n    '.join(o) + (' ERR ' + p.stderr.decode('utf-8', 'replace').strip() if p.stderr else '') + ' [%d]' % p.returncode))
    shutil.rmtree(d)
    if outs[0] == outs[1]:
        same += 1
        if show_same:
            print('SAME', l[:150])
    else:
        print('DIFF', l)
        print('  orig:', outs[0][:1500])
        print('  mine:', outs[1][:1500])
print('%d/%d same' % (same, len(lines)))

