#!/usr/bin/env python3
"""edgedump.py [-m] file.bimcraft id x0 y0 x1 y1 step [view]
Probes linework of element `id` at every grid point of the box (step mm apart) and prints the
distinct edges (from, to) found, with how many grid points picked each."""
import subprocess, sys, os, json, itertools
from concurrent.futures import ThreadPoolExecutor
a = sys.argv[1:]
exe = '/workspace/executable'
if a[0] == '-m':
    exe = os.environ['MINE']; a = a[1:]
f, eid = a[0], int(a[1])
x0, y0, x1, y1, step = map(float, a[2:7])
view = a[7] if len(a) > 7 else None
pts = []
x = x0
while x <= x1 + 1e-9:
    y = y0
    while y <= y1 + 1e-9:
        pts.append((round(x, 3), round(y, 3)))
        y += step
    x += step
def probe(p):
    c = {"id": eid, "at": [p[0], p[1]], "style": "Wide Lines"}
    if view:
        c["view"] = view
    r = subprocess.run([exe, 'run', f, '--cmd', 'linework ' + json.dumps(c)], capture_output=True, cwd='/tmp/views-notes')
    out = r.stdout.decode().strip().split('\n')[-1]
    if r.returncode != 0:
        return p, None
    try:
        d = json.loads(out)
        return p, (tuple(d['from']), tuple(d['to']))
    except Exception:
        return p, None
with ThreadPoolExecutor(16) as ex:
    res = list(ex.map(probe, pts))
edges = {}
for p, e in res:
    if e is None:
        continue
    k = (tuple(round(v, 2) for v in e[0]), tuple(round(v, 2) for v in e[1]))
    edges.setdefault(k, []).append(p)
for k, ps in sorted(edges.items()):
    print(k, len(ps))
print('points', len(pts), 'with edge', sum(1 for _, e in res if e))

