/// The corners of walls meeting end to end, each wall's counter-clockwise and clockwise of the way
/// it leaves the joint: where its face meets the face of the wall next round. None where a corner
/// lies further along a wall's face from its end than the wall is thick (too sharp to mitre).
fn mitre(ws: &[Wall], group: &[(usize, bool)]) -> Option<Vec<((usize, bool), [f64; 2], [f64; 2])>> {
    let mut members: Vec<(usize, bool, [f64; 2], [f64; 2], f64)> = group
        .iter()
        .map(|(k, s)| {
            let wk = &ws[*k];
            let vk = leaving(wk, *s);
            (*k, *s, end_point(&wk.centre, *s), vk, vk[1].atan2(vk[0]))
        })
        .collect();
    members.sort_by(|a, b| a.4.partial_cmp(&b.4).unwrap_or(std::cmp::Ordering::Equal));
    let m = members.len();
    let mut out = Vec::new();
    for me in 0..m {
        let (k, s, pk, vk, _) = members[me];
        let nk = perp(vk);
        let tk = ws[k].t;
        let next = members[(me + 1) % m];
        let prev = members[(me + m - 1) % m];
        let ccw_face = add(pk, mul(nk, tk / 2.0));
        let ccw = {
            let (_, _, pn, vn, _) = next;
            let tn = ws[next.0].t;
            meet(ccw_face, vk, sub(pn, mul(perp(vn), tn / 2.0)), vn).unwrap_or(ccw_face)
        };
        let cw_face = sub(pk, mul(nk, tk / 2.0));
        let cw = {
            let (_, _, pp, vp, _) = prev;
            let tp = ws[prev.0].t;
            meet(cw_face, vk, add(pp, mul(perp(vp), tp / 2.0)), vp).unwrap_or(cw_face)
        };
        for (c, f) in [(ccw, ccw_face), (cw, cw_face)] {
            if dot(sub(c, f), vk).abs() > tk + 1e-9 {
                return None;
            }
        }
        out.push(((k, s), ccw, cw));
    }
    Some(out)
}

