}

struct Parser<'a> {
    t: Vec<Tok>,
    i: usize,
    vars: &'a dyn Fn(&str) -> Option<f64>,
}

impl Parser<'_> {
    fn peek(&self) -> Option<&Tok> {
        self.t.get(self.i)
    }
    fn expr(&mut self) -> Option<f64> {
        let mut v = self.term()?;
        while let Some(Tok::Op(c @ ('+' | '-'))) = self.peek().cloned() {
            self.i += 1;
            let r = self.term()?;
            v = if c == '+' { v + r } else { v - r };
        }
        Some(v)
    }
    fn term(&mut self) -> Option<f64> {
        let mut v = self.factor()?;
        while let Some(Tok::Op(c @ ('*' | '/'))) = self.peek().cloned() {
            self.i += 1;
            let r = self.factor()?;
            v = if c == '*' { v * r } else { v / r };
        }
        Some(v)
    }
    fn factor(&mut self) -> Option<f64> {
        match self.peek().cloned()? {
            Tok::Op('-') => {
                self.i += 1;
                Some(-self.factor()?)
            }
            Tok::Op('+') => {
                self.i += 1;
                self.factor()
            }
            Tok::Op('(') => {
                self.i += 1;
                let v = self.expr()?;
                if self.peek() != Some(&Tok::Op(')')) {
                    return None;
                }
                self.i += 1;
                Some(v)
            }
            Tok::Num(n) => {
                self.i += 1;
                Some(n)
            }
            Tok::Name(n) => {
                self.i += 1;
                if self.peek() == Some(&Tok::Op('(')) {
                    self.i += 1;
                    let mut args = Vec::new();
                    if self.peek() != Some(&Tok::Op(')')) {
                        loop {
                            args.push(self.expr()?);
                            match self.peek() {
                                Some(Tok::Op(',')) => self.i += 1,
                                _ => break,
                            }
                        }
                    }
                    if self.peek() != Some(&Tok::Op(')')) {
                        return None;
                    }
                    self.i += 1;
                    return call(&n.to_lowercase(), &args);
                }
                (self.vars)(&n)
            }
            _ => None,
        }
    }
}

fn call(f: &str, a: &[f64]) -> Option<f64> {
    Some(match (f, a.len()) {
        ("min", n) if n >= 1 => a.iter().cloned().fold(f64::INFINITY, f64::min),
        ("max", n) if n >= 1 => a.iter().cloned().fold(f64::NEG_INFINITY, f64::max),
        ("abs", 1) => a[0].abs(),
        ("sqrt", 1) => a[0].sqrt(),
        ("round", 1) => a[0].round(),
        _ => return None,
    })
}

/// A formula's value, its names the family's parameters.
pub fn eval(v: &Value, vars: &dyn Fn(&str) -> Option<f64>) -> Option<f64> {
    match v {
        Value::Num(n) => Some(n.as_f64()),
        Value::Str(s) => {
            let t = tokens(s)?;
            let mut p = Parser { t, i: 0, vars };
            let x = p.expr()?;
            if p.i != p.t.len() {
                return None;
            }
            Some(x)
        }
        _ => None,
    }
}

// ---------------------------------------------------------------- the family's values

/// A door's or a window's value of a family parameter: its own, its type's, else the family's;
/// `Wall Thickness` its wall's.
fn value_of(pr: &Project, e: &Value, fam: &Value, type_name: &str, wall_t: f64, name: &str) -> Option<f64> {
    if name == "Wall Thickness" {
        return Some(wall_t);
    }
    if let Some(x) = e.get("params").and_then(|m| m.get(name)).and_then(|x| x.as_f64()) {
        return Some(x);
    }
    if let Some(x) = fam.get("types").and_then(|t| t.get(type_name)).and_then(|t| t.get(name)).and_then(|x| x.as_f64()) {
        return Some(x);
    }
    let _ = pr;
    fam.get("parameters")?.as_arr()?.iter().find(|p| s_of(p, "name") == Some(name)).and_then(|p| f_of(p, "value"))
}

/// How many chords draw a symbol's arc: a quarter turn in 24.
const ARC_STEP: f64 = 3.75;

/// The lines a plan draws of a door or a window of a family, cut `z` mm over its sill: `place`
/// maps the family's (x, y) to plan mm, `jambs` the opening's own.
pub fn family_opening_lines(
    pr: &Project,
    e: &Value,
    wall_t: f64,
    z: f64,
    place: &dyn Fn(f64, f64) -> [f64; 2],
    jamb: &dyn Fn(f64) -> Vec<Line>,
    mirrored: bool,
) -> Option<Vec<Line>> {
    let fam_name = lib_ref_name(pr, e, "family")?;
    let fam = pr.section("families")?.get(&fam_name)?.clone();
    let type_name = super::super::tags::fields::type_name(pr, e).unwrap_or_default();
    let vars = |n: &str| value_of(pr, e, &fam, &type_name, wall_t, n);
    let width = vars("Width")?;
    let mut out = Vec::new();
    out.extend(jamb(width));
    if let Some(forms) = fam.get("forms").and_then(|f| f.as_arr()) {
        for f in forms {
            if f.get("void").and_then(|v| v.as_bool()) == Some(true) {
                continue;
            }
            if s_of(f, "plane").unwrap_or("xy") != "xy" {
                continue;
            }
            if f.get("visible").and_then(|v| v.as_bool()) == Some(false) {
                continue;
            }
            let from = f.get("from").and_then(|x| eval(x, &vars)).unwrap_or(0.0);
            let to = match f.get("to").and_then(|x| eval(x, &vars)) {
                Some(t) => t,
                None => continue,
            };
            if !(from <= z && z < to) {
                continue;
            }
            let Some(profile) = f.get("profile").and_then(|p| p.as_arr()) else { continue };
            let pts: Option<Vec<[f64; 2]>> = profile
                .iter()
                .map(|q| {
                    let q = q.as_arr()?;
                    Some(place(eval(q.first()?, &vars)?, eval(q.get(1)?, &vars)?))
                })
                .collect();
            if let Some(mut pts) = pts {
                if pts.len() >= 2 {
                    // mirrored, a profile is taken the other way round so it keeps its turn
                    if mirrored {
                        pts.reverse();
                    }
                    out.push(Line::ring(pts));
                }
            }
        }
    }
    if let Some(symbols) = fam.get("symbols").and_then(|s| s.as_arr()) {
        for s in symbols {
            if s.get("visible").and_then(|v| v.as_bool()) == Some(false) {
                continue;
            }
            if let Some(l) = s.get("line").and_then(|l| l.as_arr()) {
                let pts: Option<Vec<[f64; 2]>> = l
                    .iter()
                    .map(|q| {
                        let q = q.as_arr()?;
                        Some(place(eval(q.first()?, &vars)?, eval(q.get(1)?, &vars)?))
                    })
                    .collect();
                if let Some(pts) = pts {
                    if pts.len() >= 2 {
                        out.push(Line::open(pts));
                    }
                }
            } else if let Some(a) = s.get("arc") {
                let Some(c) = a.get("centre").and_then(|c| c.as_arr()) else { continue };
                let (Some(cx), Some(cy)) = (c.first().and_then(|x| eval(x, &vars)), c.get(1).and_then(|x| eval(x, &vars))) else {
                    continue;
                };
                let Some(r) = a.get("radius").and_then(|x| eval(x, &vars)) else { continue };
                let from = a.get("from").and_then(|x| eval(x, &vars)).unwrap_or(0.0);
                let to = a.get("to").and_then(|x| eval(x, &vars)).unwrap_or(360.0);
                let sweep = to - from;
                let n = ((sweep.abs() / ARC_STEP) - 1e-9).ceil().max(1.0) as usize;
                let pts: Vec<[f64; 2]> = (0..=n)
                    .map(|k| {
                        let t = (from + sweep * k as f64 / n as f64).to_radians();
                        place(cx + r * t.cos(), cy + r * t.sin())
                    })
                    .collect();
                out.push(Line::open(pts));
            }
        }
    }
    Some(out)
}

