172	/// A door's or a window's value of a family parameter: its own, its type's, else the family's;
173	/// `Wall Thickness` its wall's.
174	fn value_of(pr: &Project, e: &Value, fam: &Value, type_name: &str, wall_t: f64, name: &str) -> Option<f64> {
175	    if name == "Wall Thickness" {
176	        return Some(wall_t);
177	    }
178	    if let Some(x) = e.get("params").and_then(|m| m.get(name)).and_then(|x| x.as_f64()) {
179	        return Some(x);
180	    }
181	    if let Some(x) = fam.get("types").and_then(|t| t.get(type_name)).and_then(|t| t.get(name)).and_then(|x| x.as_f64()) {
182	        return Some(x);
183	    }
184	    let _ = pr;
185	    fam.get("parameters")?.as_arr()?.iter().find(|p| s_of(p, "name") == Some(name)).and_then(|p| f_of(p, "value"))
186	}
