import subprocess, sys, json
for name in sys.argv[1:]:
    p = subprocess.run(['/workspace/executable', 'run', '--cmd', 'family ' + json.dumps({"name": name})], capture_output=True)
    d = json.loads(p.stdout.decode().strip().split('\n')[-1])
    f = d['family']
    print('==', name, f['category'], 'params', [(x['name'], x.get('value'), x.get('formula'), x.get('instance')) for x in f['parameters']])
    print('   types', json.dumps(f['types']))
    for fm in f.get('forms', []):
        g = {k: v for k, v in fm.items() if k not in ('guid',)}
        print('   form', json.dumps(g))
    for s in f.get('symbols', []):
        g = {k: v for k, v in s.items() if k not in ('guid',)}
        print('   symbol', json.dumps(g))
    for k in f:
        if k not in ('forms', 'symbols', 'parameters', 'types', 'category'):
            print('   ', k, json.dumps(f[k]))

