#!/usr/bin/env python3
"""pts.py [-m] file.bimcraft id x,y x,y ... [-v view] : linework at each point (orig, or mine with -m)."""
import subprocess, sys, os, json
a = sys.argv[1:]
exe = '/workspace/executable'
both = False
if a[0] == '-m':
    exe = os.environ['MINE']; a = a[1:]
elif a[0] == '-b':
    both = True; a = a[1:]
view = None
if '-v' in a:
    i = a.index('-v'); view = a[i + 1]; a = a[:i] + a[i + 2:]
f, eid = a[0], int(a[1])
def run(exe, x, y):
    c = {"id": eid, "at": [x, y], "style": "Wide Lines"}
    if view:
        c["view"] = view
    r = subprocess.run([exe, 'run', f, '--cmd', 'linework ' + json.dumps(c)], capture_output=True, cwd='/tmp/views-notes')
    return r.stdout.decode().strip().split('\n')[-1] if r.returncode == 0 else 'ERR ' + r.stderr.decode().strip()[-150:]
for s in a[2:]:
    x, y = map(float, s.split(','))
    o = run(exe, x, y)
    if both:
        m = run(os.environ['MINE'], x, y)
        print((x, y), 'SAME' if o == m else 'DIFF', o, '' if o == m else '\n      mine: ' + m)
    else:
        print((x, y), o)

