#!/usr/bin/env python3
"""svgmodel.py [-f in.bimcraft] [-r R] 'cmd' ... : builds the model with the original (two tiny calibration
detail lines at (-R,-R) and (R,R) added, R=3000 by default), renders the plan to SVG and prints every stroke
path in model mm (one decimal), in drawing order, with its stroke width and dash."""
import subprocess, sys, re
a = sys.argv[1:]
src = None
R = 3000.0
while a and a[0] in ('-f', '-r'):
    if a[0] == '-f':
        src = a[1]
    else:
        R = float(a[1])
    a = a[2:]
args = ['/workspace/executable', 'run'] + ([src] if src else [])
for c in a:
    args += ['--cmd', c]
args += ['--cmd', 'detail_line {"start":[%g,%g],"end":[%g,%g]}' % (-R, -R, -R + 10, -R)]
args += ['--cmd', 'detail_line {"start":[%g,%g],"end":[%g,%g]}' % (R, R, R + 10, R)]
args += ['--save', '/tmp/views-notes/_m.svg']
p = subprocess.run(args, capture_output=True, cwd='/tmp/views-notes')
if p.returncode:
    print(p.stderr.decode()); sys.exit(1)
s = open('/tmp/views-notes/_m.svg').read()
paths = []
for m in re.finditer(r'<(path|circle|text|polyline|line|rect)\b([^>]*)/?>', s):
    kind, attrs = m.group(1), m.group(2)
    if kind == 'path':
        d = re.search(r' d="([^"]*)"', attrs).group(1)
        nums = [(float(x), float(y)) for x, y in re.findall(r'(-?[\d.]+)[ ,](-?[\d.]+)', d)]
        paths.append(('path', nums, attrs, d))
    else:
        paths.append((kind, [], attrs, ''))
# calibration: the two short horizontal paths of 10 mm whose ends are farthest apart
cands = [p for p in paths if p[0] == 'path' and len(p[1]) == 2 and abs(p[1][0][1] - p[1][1][1]) < 1e-9]
best = None
for i in range(len(cands)):
    for j in range(len(cands)):
        if i == j:
            continue
        a0, b0 = cands[i][1][0], cands[j][1][0]
        if b0[0] > a0[0] and b0[1] < a0[1]:
            w1 = cands[i][1][1][0] - cands[i][1][0][0]
            w2 = cands[j][1][1][0] - cands[j][1][0][0]
            if abs(w1 - w2) < 0.2 and w1 > 0:
                d = (b0[0] - a0[0])
                if best is None or d > best[0]:
                    best = (d, a0, b0)
_, a0, b0 = best
K = (2 * R) / (b0[0] - a0[0])  # mm per px
def tm(px, py):
    return (-R + (px - a0[0]) * K, -R + (a0[1] - py) * K)
print('scale %.4f mm/px' % K)
for kind, nums, attrs, d in paths:
    if kind != 'path':
        print(kind, attrs[:150])
        continue
    if 'stroke=' not in attrs:
        fill = re.search(r'fill="([^"]*)"', attrs)
        tag = 'FILL ' + (fill.group(1) if fill else '?')
    else:
        sw = re.search(r'stroke-width="([\d.]+)"', attrs)
        dash = re.search(r'stroke-dasharray="([^"]*)"', attrs)
        col = re.search(r'stroke="([^"]*)"', attrs)
        tag = 'w=%s %s' % (sw.group(1)[:5] if sw else '?', col.group(1) if col else '')
        if dash:
            tag += ' dash=' + dash.group(1)
    pts = ' '.join('(%.1f,%.1f)' % tm(x, y) for x, y in nums)
    print(tag, pts + (' Z' if 'Z' in d else ''))

